def compute(vars):
    total_employees = vars["v2"]
    if total_employees == 0:
        return None

    ratio = vars["v1"] / total_employees
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "employee_ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
